from urllib.parse import urlencode

IGNORED_VALUES = {None, "", "all", "全部"}
VALID_ORDERS = {"updatedAt", "createdAt", "hits", "score"}


def clean(value):
    if value in IGNORED_VALUES:
        return ""
    value = str(value).strip()
    if value in IGNORED_VALUES:
        return ""
    return value


def int_or_default(value, default):
    try:
        num = int(value)
        return num if num > 0 else default
    except (TypeError, ValueError):
        return default


def execute(node_id, node_data, context):
    params = {}
    page_num = int_or_default(context.get("page_num"), 1)
    if page_num > 1:
        params["page"] = page_num

    tag = clean(context.get("tag"))
    year = clean(context.get("year"))
    area = clean(context.get("area"))
    order = clean(context.get("order")) or "updatedAt"
    keyword = clean(context.get("keyword"))

    if tag:
        params["tag"] = tag
    if year:
        params["year"] = year
    if area:
        params["area"] = area
    if order in VALID_ORDERS:
        params["order"] = order
    if keyword:
        params["q"] = keyword

    query = urlencode(params)
    context["list_path"] = "/videos" + (("?" + query) if query else "")

import html
import json
import re
from urllib.parse import parse_qs, quote, urlsplit


def decode_next_data(page_html):
    if not page_html:
        return ""
    chunks = []
    pattern = re.compile(r'self\.__next_f\.push\(\[1,"((?:\\.|[^"\\])*)"\]\)</script>', re.S)
    for match in pattern.finditer(page_html):
        raw = match.group(1)
        try:
            chunks.append(json.loads('"' + raw + '"'))
        except Exception:
            continue
    return "".join(chunks)


def find_value_start(text, key, expected=None, pos=0):
    marker = '"' + key + '"'
    while True:
        idx = text.find(marker, pos)
        if idx < 0:
            return -1
        cur = idx + len(marker)
        while cur < len(text) and text[cur].isspace():
            cur += 1
        if cur < len(text) and text[cur] == ':':
            cur += 1
            while cur < len(text) and text[cur].isspace():
                cur += 1
            if expected is None or (cur < len(text) and text[cur] == expected):
                return cur
        pos = idx + len(marker)


def extract_json_range(text, start):
    if start < 0 or start >= len(text):
        return None, start
    pairs = {"{": "}", "[": "]"}
    open_ch = text[start]
    close_ch = pairs.get(open_ch)
    if not close_ch:
        return None, start
    depth = 0
    in_string = False
    escaped = False
    for idx in range(start, len(text)):
        ch = text[idx]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        else:
            if ch == '"':
                in_string = True
            elif ch == open_ch:
                depth += 1
            elif ch == close_ch:
                depth -= 1
                if depth == 0:
                    return text[start:idx + 1], idx + 1
    return None, start


def extract_json_value(text, key, expected, pos=0, fallback=None):
    start = find_value_start(text, key, expected, pos)
    raw, end = extract_json_range(text, start)
    if raw is None:
        return fallback, pos
    try:
        return json.loads(raw), end
    except Exception:
        return fallback, end


def extract_scalar(text, key, pos=0):
    start = find_value_start(text, key, None, pos)
    if start < 0:
        return None
    if text[start] in "[{":
        return None
    if text[start] == '"':
        escaped = False
        for idx in range(start + 1, len(text)):
            ch = text[idx]
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                try:
                    value = json.loads(text[start:idx + 1])
                except Exception:
                    value = text[start + 1:idx]
                return None if value == "$undefined" else value
        return None
    end = start
    while end < len(text) and text[end] not in ",}]\n":
        end += 1
    raw = text[start:end].strip()
    if not raw or raw == "$undefined":
        return None
    try:
        return json.loads(raw)
    except Exception:
        return raw


def strip_tags(value):
    text = re.sub(r"<[^>]+>", "", value or "")
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def short_date(value):
    if not value:
        return ""
    return str(value).split("T", 1)[0]


def split_tags(value):
    if not value:
        return []
    parts = re.split(r"[,，\s]+", str(value))
    return [part.strip() for part in parts if part.strip()]


def normalize_score(value):
    try:
        score = float(value)
    except (TypeError, ValueError):
        return None
    return score if score > 0 else None


def chapter_label(source_name, episode_name):
    source_name = str(source_name or "").strip()
    episode_name = str(episode_name or "").strip() or "播放"
    return (source_name + " " + episode_name).strip()


def execute(node_id, node_data, context):
    data = decode_next_data(context.get("list_html") or "")
    videos, videos_end = extract_json_value(data, "videos", "[", 0, [])
    tags, _ = extract_json_value(data, "tags", "[", videos_end, [])
    years, _ = extract_json_value(data, "years", "[", videos_end, [])
    areas, _ = extract_json_value(data, "areas", "[", videos_end, [])

    items = []
    for video in videos if isinstance(videos, list) else []:
        if not isinstance(video, dict):
            continue
        slug = video.get("slug") or video.get("sourceId") or video.get("id")
        if not slug:
            continue
        title = video.get("name") or video.get("nameOriginal") or video.get("sub") or str(slug)
        tags_for_item = split_tags(video.get("tag"))
        category = str(video.get("year") or "")
        if tags_for_item:
            category = ", ".join(tags_for_item[:2])
        misc = video.get("remarks") or ""
        if not misc and video.get("episodeCount"):
            misc = "更新至第%s集" % video.get("episodeCount")
        items.append({
            "id": "/video/%s" % slug,
            "title": title,
            "cover": video.get("pic") or video.get("picThumb") or "",
            "rating": normalize_score(video.get("score")),
            "misc": misc,
            "category": category,
            "uploader": video.get("sourceName") or video.get("studio") or "TvTFun",
            "uploaded_at": short_date(video.get("updatedAt") or video.get("publishedAt") or video.get("createdAt")),
            "media_type": "video",
        })

    total = extract_scalar(data, "total", videos_end)
    page = extract_scalar(data, "page", videos_end) or 1
    page_size = extract_scalar(data, "pageSize", videos_end) or 24
    try:
        total_pages = (int(total) + int(page_size) - 1) // int(page_size) if total is not None else None
    except Exception:
        total_pages = None

    context["available_tags"] = tags if isinstance(tags, list) else []
    context["available_years"] = years if isinstance(years, list) else []
    context["available_areas"] = areas if isinstance(areas, list) else []
    context["search_result"] = {
        "total": total,
        "totalPages": total_pages,
        "page": page,
        "items": items,
    }

