def chapter_label(source_name, episode_name):
    source_name = str(source_name or "").strip()
    episode_name = str(episode_name or "").strip() or "播放"
    return (source_name + " " + episode_name).strip()


def bangumi_episode_id(episode):
    """Normalize a dependable Bangumi episode identifier.

    Args:
        episode: The provider episode record.

    Returns:
        A positive decimal identifier, or an empty string when unavailable.
    """
    value = episode.get("bgmEpisodeId")
    if isinstance(value, bool) or not isinstance(value, (int, str)):
        return ""
    value = str(value).strip()
    if not re.fullmatch(r"[0-9]+", value):
        return ""
    try:
        number = int(value)
    except ValueError:
        return ""
    return str(number) if number > 0 else ""


def episode_name(episode):
    """Normalize episode-name whitespace without guessing episode numbers.

    Args:
        episode: The provider episode record.

    Returns:
        The exact normalized name, or an empty string for missing generic names.
    """
    value = episode.get("name")
    if not isinstance(value, str):
        return ""
    value = re.sub(r"\s+", " ", value).strip()
    return "" if value in {"", "$undefined", "播放"} else value


def source_identity(source, index):
    """Identify a source independently of its display name.

    Args:
        source: The provider source record.
        index: The source position used when stable identifiers are absent.

    Returns:
        The source code, provider identifier, or an index-based identifier.
    """
    for field in ("fromCode", "id"):
        value = source.get(field)
        if isinstance(value, (int, str)) and not isinstance(value, bool):
            value = str(value).strip()
            if value not in {"", "$undefined"}:
                return value
    return f"index:{index}"


def playback_candidate(slug, source, source_index, episode, episode_index):
    """Describe one resolvable source without requesting its media.

    Args:
        slug: The current video's provider slug.
        source: The selected source record.
        source_index: The exact source position in the provider response.
        episode: The selected episode record.
        episode_index: The exact episode position within the selected source.

    Returns:
        The internal candidate fields, or an empty mapping without a resolver ID.
    """
    episode_id = episode.get("id")
    if isinstance(episode_id, bool) or not isinstance(episode_id, (int, str)):
        return {}
    episode_id = str(episode_id).strip()
    if episode_id in {"", "$undefined"}:
        return {}
    chapter_id = f"/video/{slug}/play?source={source_index}&episode={episode_index}"
    source_name = source.get("name") or f"线路{source_index + 1}"
    return {
        "chapter_id": chapter_id,
        "title": chapter_label(source_name, episode.get("name")),
        "episode_id": episode_id,
        "source_id": source_identity(source, source_index),
        "resolve_url": (
            "https://www.tvtfun.net/api/videos/resolve-play-url?episodeId="
            + quote(episode_id, safe="")
        ),
        "referer": "https://www.tvtfun.net" + chapter_id,
    }


def build_preflight_candidates(video, slug, chapter_id):
    """Select the requested episode and at most one dependable alternate source.

    Args:
        video: The parsed video record from the existing details response.
        slug: The current video's provider slug.
        chapter_id: The explicitly requested chapter URL or relative path.

    Returns:
        The ordered candidate list and original episode's danmaku URL. Invalid
        selections produce an empty list and URL. Ambiguous episode identities
        retain only the requested source instead of guessing another episode.
    """
    if not isinstance(chapter_id, str) or not chapter_id:
        return [], ""
    try:
        parsed = urlsplit(chapter_id)
        query = parse_qs(parsed.query, keep_blank_values=True)
    except ValueError:
        return [], ""
    if parsed.path != f"/video/{slug}/play":
        return [], ""
    indices = []
    for field in ("source", "episode"):
        values = query.get(field, [])
        if len(values) != 1 or not re.fullmatch(r"[0-9]+", values[0]):
            return [], ""
        try:
            indices.append(int(values[0]))
        except ValueError:
            return [], ""
    source_index, episode_index = indices
    sources = video.get("playSources")
    if not isinstance(sources, list) or source_index >= len(sources):
        return [], ""
    source = sources[source_index]
    if not isinstance(source, dict):
        return [], ""
    episodes = source.get("episodes")
    if not isinstance(episodes, list) or episode_index >= len(episodes):
        return [], ""
    episode = episodes[episode_index]
    if not isinstance(episode, dict):
        return [], ""
    current = playback_candidate(slug, source, source_index, episode, episode_index)
    if not current:
        return [], ""
    candidates = [current]
    video_id = str(video.get("id") or "")
    danmaku_url = (
        "https://www.tvtfun.net/api/danmaku?videoId="
        + quote(video_id, safe="")
        + "&episodeId="
        + quote(current["episode_id"], safe="")
    )
    bgm_id = bangumi_episode_id(episode)
    name = episode_name(episode)
    identity = bgm_id or name
    if not identity:
        return candidates, danmaku_url
    identifier = bangumi_episode_id if bgm_id else episode_name
    matches = [
        item
        for item in episodes
        if isinstance(item, dict) and identifier(item) == identity
    ]
    if len(matches) != 1:
        return candidates, danmaku_url
    for other_index, other_source in enumerate(sources):
        if other_index == source_index or not isinstance(other_source, dict):
            continue
        if source_identity(other_source, other_index) == current["source_id"]:
            continue
        other_episodes = other_source.get("episodes")
        if not isinstance(other_episodes, list):
            continue
        matches = [
            (index, item)
            for index, item in enumerate(other_episodes)
            if isinstance(item, dict) and identifier(item) == identity
        ]
        if len(matches) != 1:
            continue
        other_episode_index, other_episode = matches[0]
        if not bgm_id and bangumi_episode_id(other_episode):
            continue
        candidate = playback_candidate(
            slug, other_source, other_index, other_episode, other_episode_index
        )
        if candidate and candidate["episode_id"] != current["episode_id"]:
            candidates.append(candidate)
            break
    return candidates, danmaku_url


def execute(node_id, node_data, context):
    """Populate public details and internal preflight candidates from one response.

    Args:
        node_id: The identifier of the executing script node.
        node_data: The saved script-node configuration.
        context: The workflow context receiving unchanged public details and
            internal candidates for the explicitly selected episode. Playback
            setup and probing share a deadline established before the session
            request, leaving room within the frontend request timeout.
    """
    context["preflight_deadline"] = time.monotonic() + 36
    data = decode_next_data(context.get("detail_html") or "")
    video, _ = extract_json_value(data, "video", "{", 0, {})
    if not isinstance(video, dict):
        video = {}

    slug = video.get("slug") or str(context.get("id") or "").strip("/").split("/")[-1]
    tags = split_tags(video.get("tag"))
    chapters = []
    sources = video.get("playSources") or []
    for source_index, source in enumerate(sources if isinstance(sources, list) else []):
        if not isinstance(source, dict):
            continue
        source_name = source.get("name") or "线路%s" % (source_index + 1)
        episodes = source.get("episodes") or []
        for episode_index, episode in enumerate(
            episodes if isinstance(episodes, list) else []
        ):
            if not isinstance(episode, dict):
                continue
            chapters.append(
                {
                    "id": "/video/%s/play?source=%s&episode=%s"
                    % (slug, source_index, episode_index),
                    "title": chapter_label(source_name, episode.get("name")),
                }
            )

    context["detail_video_id"] = video.get("id") or ""
    context["detail_slug"] = slug
    context["detail_title"] = (
        video.get("name") or video.get("nameOriginal") or video.get("sub") or "TvTFun"
    )
    context["detail_cover"] = video.get("pic") or video.get("picThumb") or ""
    context["detail_category"] = (
        ", ".join(tags[:3]) if tags else str(video.get("year") or "")
    )
    context["detail_misc"] = video.get("remarks") or ""
    context["detail_uploader"] = (
        video.get("sourceName") or video.get("studio") or "TvTFun"
    )
    context["detail_uploaded_at"] = short_date(
        video.get("updatedAt") or video.get("publishedAt") or video.get("createdAt")
    )
    context["detail_description"] = strip_tags(
        video.get("content") or video.get("blurb") or ""
    )
    context["detail_chapters"] = chapters
    context["has_chapter_id"] = bool(context.get("chapter_id"))
    candidates, danmaku_url = build_preflight_candidates(
        video, slug, context.get("chapter_id")
    )
    context["preflight_candidates"] = candidates
    context["preflight_danmaku_url"] = danmaku_url

"""Validate bounded TvTfun media probes without performing external operations."""
import hashlib
import json
import re
from urllib.parse import unquote, urljoin, urlsplit, urlunsplit
MP4_LIMIT = 4096
SEGMENT_LIMIT = 8 * 1024 * 1024
"""Advance one TvTFun probe using the existing HTTP and loop nodes."""
import json
import time
from urllib.parse import quote

def _url(value, base=""):
    """Normalize an HTTP media URL while preserving its query.

    Args:
        value: The absolute or relative URI to resolve.
        base: The HTTP URL used to resolve a relative URI.

    Returns:
        A URL without a fragment, or an empty string for invalid input.
    """
    if not isinstance(value, str) or not value:
        return ""
    if any(ord(char) <= 32 or ord(char) == 127 for char in value) or "\\" in value:
        return ""
    try:
        parts = urlsplit(urljoin(base, value))
        if (
            parts.scheme not in {"http", "https"}
            or not parts.hostname
            or parts.username is not None
            or parts.password is not None
            or "%" in parts.hostname
        ):
            return ""
        if parts.port is not None and not 0 < parts.port <= 65535:
            return ""
        return urlunsplit(parts._replace(fragment=""))
    except ValueError:
        return ""

def is_error_media(value):
    """Recognize the provider's confirmed error-video object.

    Args:
        value: A media URL, including possible query or fragment suffixes.

    Returns:
        Whether the URL points to the verified three-second error placeholder.
    """
    url = _url(value)
    if not url:
        return False
    parts = urlsplit(url)
    return (
        parts.hostname.rstrip(".").lower() == "kjjsaas-sh.oss-cn-shanghai.aliyuncs.com"
        and unquote(parts.path)
        == "/u/3401405881/20240818-936952-fc31b16575e80a7562cdb1f81a39c6b0.mp4"
    )

def playback_headers(data):
    """Keep supported resolver headers without propagating credentials.

    Args:
        data: The resolver's optional media header mapping.

    Returns:
        Valid `Referer` and `User-Agent` overrides supported by the media proxy.
    """
    if not isinstance(data, dict):
        return {}
    headers = {}
    for key, value in data.items():
        if not isinstance(key, str) or not isinstance(value, str):
            continue
        value = value.strip()
        if not value or any(ord(char) < 32 or ord(char) > 126 for char in value):
            continue
        if key.lower() == "referer":
            referer = _url(value)
            if referer:
                headers["Referer"] = referer
        elif key.lower() == "user-agent":
            headers["User-Agent"] = value
    return headers

def parse_resolver(data):
    """Classify a resolver payload as a direct media URL or a share page.

    Args:
        data: The decoded resolver `data` object containing `url`, `type`,
            and optional upstream request headers.

    Returns:
        A dictionary with `url` and `type`, or an empty dictionary if unsupported.
        The type is `mp4`, `hls`, or `share`. Share results retain the resolver's
        original type as `media_type` for parsing extensionless media URLs.
        Supported media request headers are retained. Known error placeholders
        and malformed payloads produce an empty dictionary.
    """
    if not isinstance(data, dict):
        return {}
    url = _url(data.get("url"))
    if not url or is_error_media(url):
        return {}
    headers = playback_headers(data.get("headers"))
    extra = {"headers": headers} if headers else {}
    path = urlsplit(url).path.lower()
    media_type = str(data.get("type") or "").lower().strip()
    if "/share/" in path:
        return {"url": url, "type": "share", "media_type": media_type, **extra}
    if media_type in {
        "hls",
        "m3u8",
        "application/x-mpegurl",
        "application/vnd.apple.mpegurl",
    }:
        return {"url": url, "type": "hls", **extra}
    if media_type in {"mp4", "video/mp4"}:
        return {"url": url, "type": "mp4", **extra}
    if path.endswith(".m3u8"):
        return {"url": url, "type": "hls", **extra}
    if path.endswith(".mp4"):
        return {"url": url, "type": "mp4", **extra}
    return {}

def prepare_media(media):
    """Choose the first probe step for a normalized resolver result.

    Args:
        media: The validated resolver or share-page result.

    Returns:
        A branch-local probe descriptor, empty for unsupported media.
    """
    kind = media.get("type")
    if kind not in {"share", "hls", "mp4"}:
        return {"stage": "failed"}
    return {
