    Args:
        value: The text following an HLS tag's colon.

    Returns:
        The attribute dictionary, or an empty dictionary for malformed input.
    """
    result = {}
    offset = 0
    pattern = r'([A-Z0-9-]+)=("[^"\r\n]*"|[^,\s]+)(?:,|$)'
    for match in re.finditer(pattern, value):
        if match.start() != offset or match[1] in result:
            return {}
        result[match[1]] = match[2].strip('"')
        offset = match.end()
    return result if offset == len(value) else {}

