            if not first:
                first = {"kind": "media", "url": url, "encrypted": bool(key_url)}
                if key_url:
                    first["key_url"] = key_url
            pending = False
    return first if not pending else {}

def _headers(data):
    """Read normalized response headers and reject encoded or textual media.

    Args:
        data: A probe dictionary containing selected response `headers`.

    Returns:
        Normalized headers, or `None` for unusable media headers.
    """
    headers = data.get("headers", {})
    if not isinstance(headers, dict):
        return None
    headers = {str(key).lower(): str(value).strip() for key, value in headers.items()}
    encoding = headers.get("content-encoding", headers.get("encoding", "")).lower()
    media_type = headers.get("content-type", "").split(";", 1)[0].lower()
    if encoding not in {"", "identity"} or media_type.startswith("text/"):
        return None
    if media_type in {"application/json", "application/xml", "application/xhtml+xml"}:
        return None
    return headers

def _prefix(data):
    """Decode at most the first 512 response bytes from their hexadecimal form.

    Args:
        data: The probe dictionary containing `header_hex`.

    Returns:
        The bounded byte prefix, or empty bytes for missing or malformed input.
    """
    value = data.get("header_hex")
    if not isinstance(value, str):
        return b""
    try:
        return bytes.fromhex(value[:1024])
    except ValueError:
        return b""

def _complete(data, headers, expected):
    """Check the actual and declared response body lengths.

    Args:
        data: The probe dictionary containing the actual `body_length`.
        headers: The normalized response headers.
        expected: The exact expected number of body bytes.

    Returns:
        Whether the actual body and optional declared length match exactly.
    """
    length = headers.get("content-length", "")
    return data.get("body_length") == expected and (
        not length or (length.isdigit() and int(length) == expected)
    )

def validate_segment(data):
    """Validate a complete bounded TS segment or AES-128 encrypted segment.

    Args:
        data: The GET `status`, selected `headers`, prior HEAD `size`, actual
            `body_length`, initial `header_hex`, and optional `encrypted` flag.

    Returns:
        Whether the segment is complete and passes TS sync checks or encrypted
        block-size checks. Encrypted input also requires a separately valid key;
        its transport-stream contents cannot be verified without decryption.
    """
    headers = _headers(data)
    size = data.get("size")
    if (
        headers is None
        or data.get("status") != 200
        or not isinstance(size, int)
        or not 0 < size <= SEGMENT_LIMIT
        or not _complete(data, headers, size)
    ):
        return False
    prefix = _prefix(data)
    if not prefix or prefix.lstrip().lower().startswith(
        (b"<!doctype", b"<html", b"<?xml", b"<head", b"<body", b"#extm3u")
    ):
        return False
    if data.get("encrypted") is True:
        return size % 16 == 0
    if size % 188 != 0:
        return False
    offsets = range(0, min(size, 3 * 188), 188)
    return all(offset < len(prefix) and prefix[offset] == 0x47 for offset in offsets)

def validate_key(data):
    """Validate a complete AES-128 key response.

    Args:
        data: The response `status`, actual `body_length`, and optional `headers`.

    Returns:
        Whether the successful response contains exactly sixteen key bytes.
    """
    headers = _headers(data)
    return (
        headers is not None
        and data.get("status") == 200
        and _complete(data, headers, 16)
    )

def prepare_media(media):
    """Choose the first probe step for a normalized resolver result.

    Args:
        media: The validated resolver or share-page result.

    Returns:
        A branch-local probe descriptor, empty for unsupported media.
    """
    kind = media.get("type")
    if kind not in {"share", "hls", "mp4"}:
        return {"stage": "failed"}
    return {
        "stage": {"share": "share", "hls": "manifest", "mp4": "mp4"}[kind],
        "url": media["url"],
        "media": media,
    }

def next_hls_resource(probe, response, depth):
    """Parse a playlist and select its next bounded probe resource.

    Args:
        probe: The current branch-local descriptor.
        response: The playlist GET response summary.
        depth: Whether this is the initial or child playlist.

    Returns:
        An updated descriptor for a child, key or segment, or a failed stage.
    """
    if response.get("status") != 200 or not cors_allowed(response.get("headers")):
        return {**probe, "stage": "failed"}
    playlist = parse_hls(
        {"url": response["url"], "text": response.get("text", ""), "depth": depth}
    )
    if playlist.get("kind") == "master" and depth == 0:
        return {**probe, "stage": "child", "url": playlist["url"]}
    if playlist.get("kind") != "media":
        return {**probe, "stage": "failed"}
    return {
        **probe,
        "stage": "key" if playlist.get("key_url") else "segment",
        "url": playlist.get("key_url") or playlist["url"],
        "hls": playlist,
        "playback": response["url"],
    }

def advance_probe(probe, response, head):
    """Advance a bounded share or HLS probe after one complete HTTP response.

    Args:
        probe: The branch descriptor for the resource just read.
        response: The bounded GET response summary.
        head: Size metadata from the matching HEAD response.

    Returns:
        The next branch descriptor, marked `ready` only after a valid segment.
    """
    stage = probe["stage"]
    if stage == "share":
        media = probe["media"]
        value = (
            parse_share(
                {
                    "url": response.get("url", media["url"]),
                    "html": response.get("text", ""),
                    "type": media.get("media_type", ""),
                    "headers": media.get("headers"),
                }
            )
            if response.get("status") == 200
            else {}
        )
        return prepare_media(value)
    if stage in {"manifest", "child"}:
        return next_hls_resource(probe, response, int(stage == "child"))
    if stage == "key":
        if not validate_key(response) or not cors_allowed(response.get("headers")):
            return {**probe, "stage": "failed"}
        return {
            **probe,
            "stage": "segment",
            "url": probe["hls"]["url"],
            "key_checked": True,
        }
    if stage == "segment":
        encrypted = bool(probe["hls"].get("key_url"))
        valid = (
            validate_segment({**response, **head, "encrypted": encrypted})
            and cors_allowed(response.get("headers"))
            and (not encrypted or probe.get("key_checked", False))
        )
        return {**probe, "stage": "ready" if valid else "failed"}
    return {**probe, "stage": "failed"}

def execute(node_id, node_data, context):
    """Process one isolated TvTFun preflight stage.

    Args:
        node_id: The executing node identifier.
        node_data: The node configuration.
        context: The request context receiving stage-specific results once.
    """
    step = max(context['probe_b'])
    probe = {"stage": "failed"}
    if not context.get("preflight_winner") and time.monotonic() < context["preflight_deadline"]:
        probe = advance_probe(context['probe_b'][step], context['probe_body_b'][step], context['probe_head_b_checked'][step])
    context['probe_b'] = {str(int(step) + 1): probe}
    if probe["stage"] == "ready":
        context['qualified_b'] = {**context["preflight_candidates"][1], "url": probe["playback"], "video_type": "hls", "media_headers": probe["media"].get("headers", {}), "completed": time.monotonic_ns()}

